(function() {
    'use strict';

    class StatsBenchAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'StatsBench: Business Statistics Lab';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    title: 'A/B Testing: Website Redesign',
                    topic: 'Hypothesis Testing',
                    context: '<strong>Scenario:</strong> Your e-commerce site currently converts at 3.2%. The UX team built a new design and ran an A/B test with 1,000 visitors in each group.<br><br><strong>Results:</strong><br>Control group: 32 out of 1,000 converted (3.2%)<br>Treatment group: 41 out of 1,000 converted (4.1%)<br><br><strong>Your tasks:</strong><br>1. Estimate the one-sided p-value of this test (as a percentage)<br>2. How many visitors per group would you need to reliably detect a 1 percentage point lift (from 3.2% to 4.2%) with 80% power at the 5% significance level?',
                    input1Label: 'Estimated p-value (%)',
                    input1Min: 0.1, input1Max: 50, input1Default: 5, input1Step: 0.1,
                    input2Label: 'Required sample size per group',
                    input2Min: 100, input2Max: 50000, input2Default: 1000, input2Step: 100,
                    correct1: 14.2,
                    correct2: 5584,
                    tol1: 3,
                    tol2: 1000,
                    explanation: '<strong>Solution:</strong><br>The pooled proportion is 0.0365. The z-statistic is (0.041 - 0.032) / 0.00839 = 1.07.<br>One-sided p-value = P(Z > 1.07) = 14.2%. This is NOT significant at 5%.<br><br>For sample size: n = (1.96 + 0.84)^2 x 2 x 0.037 x 0.963 / 0.01^2 = 5,584 per group.'
                },
                {
                    title: 'Customer Churn Prediction',
                    topic: 'Bayesian Updating',
                    context: '<strong>Scenario:</strong> Your company has a 20% annual customer churn rate. The data science team built a predictive model with 85% sensitivity (correctly identifies churners) and a 10% false positive rate (incorrectly flags loyal customers).<br><br>A customer has just been flagged by the model as likely to churn.<br><br><strong>Your tasks:</strong><br>1. Estimate the probability this flagged customer will actually churn (%)<br>2. If the base churn rate dropped to 5%, what would be the probability for a flagged customer (%)?',
                    input1Label: 'Probability flagged customer churns (%)',
                    input1Min: 0, input1Max: 100, input1Default: 50, input1Step: 0.1,
                    input2Label: 'Probability if base rate is 5% (%)',
                    input2Min: 0, input2Max: 100, input2Default: 50, input2Step: 0.1,
                    correct1: 68.0,
                    correct2: 30.9,
                    tol1: 5,
                    tol2: 5,
                    explanation: '<strong>Solution (Bayes Theorem):</strong><br>P(churn|flagged) = (0.85 x 0.20) / (0.85 x 0.20 + 0.10 x 0.80) = 0.17 / 0.25 = 68%<br><br>With 5% base rate: P = (0.85 x 0.05) / (0.85 x 0.05 + 0.10 x 0.95) = 0.0425 / 0.1375 = 30.9%<br><br>Key insight: the base rate dramatically affects the posterior probability.'
                },
                {
                    title: 'Quality Control: Production Line',
                    topic: 'Process Capability',
                    context: '<strong>Scenario:</strong> A factory produces precision widgets with a target diameter of 50mm. Process measurements show a mean of 50mm and standard deviation of 0.8mm. Specification limits are 48.5mm to 51.5mm.<br><br><strong>Your tasks:</strong><br>1. Calculate the process capability index Cp = (USL - LSL) / (6 x sigma)<br>2. Estimate the percentage of widgets falling outside specification limits',
                    input1Label: 'Process capability index Cp',
                    input1Min: 0.1, input1Max: 3.0, input1Default: 1.0, input1Step: 0.01,
                    input2Label: 'Estimated defective rate (%)',
                    input2Min: 0, input2Max: 30, input2Default: 5, input2Step: 0.1,
                    correct1: 0.63,
                    correct2: 6.1,
                    tol1: 0.05,
                    tol2: 1.5,
                    explanation: '<strong>Solution:</strong><br>Cp = (51.5 - 48.5) / (6 x 0.8) = 3.0 / 4.8 = 0.625<br><br>Z-scores: (48.5 - 50)/0.8 = -1.875 and (51.5 - 50)/0.8 = +1.875<br>P(outside) = 2 x P(Z < -1.875) = 2 x 0.0304 = 6.1%<br><br>A Cp below 1.0 means the process spread exceeds the spec width — improvement is needed.'
                },
                {
                    title: 'Demand Forecasting',
                    topic: 'Confidence Intervals',
                    context: '<strong>Scenario:</strong> Over the last 36 months, average monthly demand for your product was 500 units with a standard deviation of 80 units.<br><br><strong>Your tasks:</strong><br>1. Calculate the upper bound of a 95% confidence interval for mean demand<br>2. How many months of data would you need to estimate mean demand within plus or minus 10 units at 95% confidence?',
                    input1Label: 'Upper bound of 95% CI for mean',
                    input1Min: 500, input1Max: 600, input1Default: 530, input1Step: 1,
                    input2Label: 'Required sample size (months)',
                    input2Min: 10, input2Max: 1000, input2Default: 100, input2Step: 1,
                    correct1: 526,
                    correct2: 246,
                    tol1: 5,
                    tol2: 30,
                    explanation: '<strong>Solution:</strong><br>SE = 80 / sqrt(36) = 13.33<br>Upper bound = 500 + 1.96 x 13.33 = 526.1<br><br>For margin of error = 10: n = (1.96 x 80 / 10)^2 = 15.68^2 = 245.9, so n = 246 months.<br><br>Larger samples give narrower intervals, but the relationship is square-root — doubling precision requires 4x the data.'
                },
                {
                    title: 'Customer Satisfaction Survey',
                    topic: 'Sampling & Margin of Error',
                    context: '<strong>Scenario:</strong> You plan to survey customers to estimate the proportion who are satisfied. Based on past data, you expect about 70% satisfaction. You want 95% confidence.<br><br><strong>Your tasks:</strong><br>1. What sample size is needed for a margin of error of plus or minus 3 percentage points?<br>2. If budget limits you to 200 respondents, what margin of error (%) should you expect?',
                    input1Label: 'Sample size for 3% margin of error',
                    input1Min: 50, input1Max: 5000, input1Default: 500, input1Step: 1,
                    input2Label: 'Margin of error with n=200 (%)',
                    input2Min: 1, input2Max: 20, input2Default: 5, input2Step: 0.1,
                    correct1: 897,
                    correct2: 6.4,
                    tol1: 50,
                    tol2: 1,
                    explanation: '<strong>Solution:</strong><br>n = (1.96^2 x 0.7 x 0.3) / 0.03^2 = (3.8416 x 0.21) / 0.0009 = 897<br><br>With n = 200: ME = 1.96 x sqrt(0.7 x 0.3 / 200) = 1.96 x 0.0324 = 6.4%<br><br>Notice the diminishing returns: going from 200 to 897 respondents only cuts the margin from 6.4% to 3%.'
                },
                {
                    title: 'Insurance Risk: Medical Testing',
                    topic: 'Conditional Probability & Bayes',
                    context: '<strong>Scenario:</strong> An insurance company screens for a rare condition with 1% prevalence. The test has 95% sensitivity (true positive rate) and 90% specificity (true negative rate = 10% false positive rate).<br><br>A policyholder tests positive.<br><br><strong>Your tasks:</strong><br>1. What is the probability this person actually has the condition? (%)<br>2. If the condition had a 10% prevalence instead, what would the probability be? (%)',
                    input1Label: 'Probability of condition given positive test (%)',
                    input1Min: 0, input1Max: 100, input1Default: 50, input1Step: 0.1,
                    input2Label: 'Probability if prevalence is 10% (%)',
                    input2Min: 0, input2Max: 100, input2Default: 50, input2Step: 0.1,
                    correct1: 8.8,
                    correct2: 51.4,
                    tol1: 2,
                    tol2: 5,
                    explanation: '<strong>Solution (Bayes Theorem):</strong><br>P(disease|positive) = (0.95 x 0.01) / (0.95 x 0.01 + 0.10 x 0.99) = 0.0095 / 0.1085 = 8.8%<br><br>With 10% prevalence: P = (0.95 x 0.10) / (0.95 x 0.10 + 0.10 x 0.90) = 0.095 / 0.185 = 51.4%<br><br>Key insight: with a rare condition, even a good test produces mostly false positives. This is the base rate fallacy in action.'
                },
                {
                    title: 'Portfolio Risk Assessment',
                    topic: 'Correlation & Joint Probability',
                    context: '<strong>Scenario:</strong> You are building a two-asset portfolio.<br><br><strong>Asset A:</strong> Expected return 8%, standard deviation 15%<br><strong>Asset B:</strong> Expected return 5%, standard deviation 8%<br><strong>Correlation:</strong> 0.3<br><br><strong>Your tasks:</strong><br>1. What allocation to Asset A (%) minimizes portfolio risk?<br>2. What is the portfolio standard deviation (%) at that minimum-risk allocation?',
                    input1Label: 'Allocation to Asset A for minimum risk (%)',
                    input1Min: 0, input1Max: 100, input1Default: 50, input1Step: 0.1,
                    input2Label: 'Portfolio standard deviation at min risk (%)',
                    input2Min: 1, input2Max: 20, input2Default: 10, input2Step: 0.1,
                    correct1: 12.9,
                    correct2: 7.7,
                    tol1: 3,
                    tol2: 1,
                    explanation: '<strong>Solution:</strong><br>Minimum variance weight for A: wA = (sigB^2 - rho x sigA x sigB) / (sigA^2 + sigB^2 - 2 x rho x sigA x sigB)<br>= (64 - 36) / (225 + 64 - 72) = 28 / 217 = 12.9%<br><br>Portfolio variance = 0.129^2 x 225 + 0.871^2 x 64 + 2 x 0.129 x 0.871 x 0.3 x 15 x 8 = 60.4<br>Standard deviation = 7.8%<br><br>Diversification reduces risk below both individual assets!'
                },
                {
                    title: 'Clinical Trial Design',
                    topic: 'Power Analysis',
                    context: '<strong>Scenario:</strong> A pharmaceutical company is testing a drug expected to reduce adverse event rates from 15% (control) to 10% (treatment). The trial uses a two-sided test at the 5% significance level.<br><br><strong>Your tasks:</strong><br>1. What sample size per group is needed for 80% power?<br>2. What sample size per group is needed for 90% power?',
                    input1Label: 'Sample size per group (80% power)',
                    input1Min: 50, input1Max: 5000, input1Default: 500, input1Step: 1,
                    input2Label: 'Sample size per group (90% power)',
                    input2Min: 50, input2Max: 5000, input2Default: 500, input2Step: 1,
                    correct1: 686,
                    correct2: 918,
                    tol1: 50,
                    tol2: 50,
                    explanation: '<strong>Solution:</strong><br>n = (z_alpha/2 + z_beta)^2 x (p1(1-p1) + p2(1-p2)) / (p1 - p2)^2<br><br>80% power (z_beta = 0.84): n = (1.96 + 0.84)^2 x (0.1275 + 0.09) / 0.0025 = 7.84 x 87 = 686<br><br>90% power (z_beta = 1.28): n = (1.96 + 1.28)^2 x 87 = 10.50 x 87 = 918<br><br>Increasing power from 80% to 90% requires about 34% more participants — a significant cost increase for relatively modest power gain.'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalScore: 0,
                    problemsSolved: 0,
                    bestScore: 0,
                    scoreHistory: [],
                    accuracyHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    estimate1: 0,
                    estimate2: 0
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            // NOTE: do NOT call _updateBriefing here — it resets the inputs to their
            // round defaults, which would discard the value the student just typed.
            var input1 = document.getElementById('estimate1Input');
            if (input1) decisions.estimate1 = parseFloat(input1.value);

            var input2 = document.getElementById('estimate2Input');
            if (input2) decisions.estimate2 = parseFloat(input2.value);

            var idx = Math.min((window.mySimulation.state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            if (isNaN(decisions.estimate1) || decisions.estimate1 < round.input1Min || decisions.estimate1 > round.input1Max) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('estimate1_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.estimate2) || decisions.estimate2 < round.input2Min || decisions.estimate2 > round.input2Max) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('estimate2_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var score1 = this._scoreAnswer(d.estimate1, round.correct1, round.tol1);
            var score2 = this._scoreAnswer(d.estimate2, round.correct2, round.tol2);
            var periodScore = score1 + score2;

            state.domainState.totalScore += periodScore;
            state.domainState.problemsSolved += 1;
            if (periodScore > state.domainState.bestScore) {
                state.domainState.bestScore = periodScore;
            }
            state.domainState.scoreHistory.push(periodScore);
            var avgAcc = state.domainState.totalScore / (state.domainState.problemsSolved * 100) * 100;
            state.domainState.accuracyHistory.push(Math.round(avgAcc));

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                topic: round.topic,
                estimate1: d.estimate1,
                correct1: round.correct1,
                estimate2: d.estimate2,
                correct2: round.correct2,
                score1: score1,
                score2: score2,
                periodScore: periodScore,
                totalScore: state.domainState.totalScore,
                explanation: round.explanation
            };
        }

        _scoreAnswer(submitted, correct, tolerance) {
            var diff = Math.abs(submitted - correct);
            if (diff <= tolerance) return 50;
            if (diff <= tolerance * 2) return 35;
            if (diff <= tolerance * 3) return 20;
            if (diff <= tolerance * 5) return 10;
            return 0;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.totalScore',
                (v) => Math.round(v) + ' / ' + (window.mySimulation.state.domainState.problemsSolved * 100 || 800));
            uiManager.bind('accuracyDisplay', 'domainState.totalScore',
                (v) => {
                    var solved = window.mySimulation.state.domainState.problemsSolved || 0;
                    if (solved === 0) return '0%';
                    return Math.round(v / (solved * 100) * 100) + '%';
                });
            uiManager.bind('solvedDisplay', 'domainState.problemsSolved');
            uiManager.bind('bestDisplay', 'domainState.bestScore',
                (v) => Math.round(v) + ' / 100');
        }

        getChartConfig() {
            return {
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Score per Problem',
                            data: [],
                            backgroundColor: [
                                'rgba(52,152,219,0.7)',
                                'rgba(46,204,113,0.7)',
                                'rgba(155,89,182,0.7)',
                                'rgba(241,196,15,0.7)',
                                'rgba(230,126,34,0.7)',
                                'rgba(231,76,60,0.7)',
                                'rgba(26,188,156,0.7)',
                                'rgba(52,73,94,0.7)'
                            ],
                            borderColor: [
                                'rgba(52,152,219,1)',
                                'rgba(46,204,113,1)',
                                'rgba(155,89,182,1)',
                                'rgba(241,196,15,1)',
                                'rgba(230,126,34,1)',
                                'rgba(231,76,60,1)',
                                'rgba(26,188,156,1)',
                                'rgba(52,73,94,1)'
                            ],
                            borderWidth: 2,
                            borderRadius: 6
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Score by Problem (max 100 each)' },
                            legend: { display: false }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, title: { display: true, text: 'Score' } },
                            x: { title: { display: true, text: 'Problem' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var topics = ['A/B Test', 'Bayes Churn', 'Quality', 'Forecast', 'Survey', 'Insurance', 'Portfolio', 'Trial'];
            var labels = state.domainState.scoreHistory.map(function(_, i) { return topics[i] || ('P' + (i + 1)); });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.scoreHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results ? r.results.periodScore || 0 : 0; });
            var totalScore = scores.reduce(function(s, p) { return s + p; }, 0);
            var maxPossible = scores.length * 100;
            var avgScore = totalScore / scores.length;
            var pct = Math.round(totalScore / maxPossible * 100);

            var performance = 'Novice Analyst';
            if (pct >= 40) performance = 'Developing Analyst';
            if (pct >= 60) performance = 'Competent Analyst';
            if (pct >= 75) performance = 'Proficient Analyst';
            if (pct >= 90) performance = 'Expert Statistician';

            var insights = [];
            if (pct >= 75) {
                insights.push('Strong command of statistical reasoning across multiple domains.');
            }
            if (pct < 50) {
                insights.push('Review Bayesian updating and confidence interval concepts for stronger results.');
            }
            var bayesScores = [];
            if (history[1] && history[1].results) bayesScores.push(history[1].results.periodScore);
            if (history[5] && history[5].results) bayesScores.push(history[5].results.periodScore);
            var bayesAvg = bayesScores.length > 0 ? bayesScores.reduce(function(a,b){return a+b;},0) / bayesScores.length : 0;
            if (bayesAvg < 40) {
                insights.push('Bayesian reasoning was challenging — practice with base rate problems to build intuition.');
            }

            return {
                totalScore: totalScore,
                maxPossible: maxPossible,
                percentage: pct,
                avgScore: Math.round(avgScore),
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results || !results.explanation) return null;
            var scoreMsg = '';
            if (results.periodScore >= 80) {
                scoreMsg = 'Excellent work! Score: ' + results.periodScore + '/100';
            } else if (results.periodScore >= 50) {
                scoreMsg = 'Good effort! Score: ' + results.periodScore + '/100. Review the solution below.';
            } else {
                scoreMsg = 'Score: ' + results.periodScore + '/100. Study the detailed solution below.';
            }
            return scoreMsg + '<br><br>Your answers: ' + results.estimate1 + ' and ' + results.estimate2 + '<br>Correct answers: ' + results.correct1 + ' and ' + results.correct2 + '<br><br>' + results.explanation;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.topic', label: 'Topic', i18nKey: 'col_topic' },
                { key: 'results.estimate1', label: 'Answer 1', i18nKey: 'col_answer1' },
                { key: 'results.correct1', label: 'Correct 1', i18nKey: 'col_correct1' },
                { key: 'results.estimate2', label: 'Answer 2', i18nKey: 'col_answer2' },
                { key: 'results.correct2', label: 'Correct 2', i18nKey: 'col_correct2' },
