            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.innerHTML = round.title;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = round.context;

            var badgeEl = document.getElementById('topicBadge');
            if (badgeEl) badgeEl.innerHTML = round.topic;

            var label1 = document.getElementById('estimate1Label');
            if (label1) label1.innerHTML = round.input1Label;

            var label2 = document.getElementById('estimate2Label');
            if (label2) label2.innerHTML = round.input2Label;

            var input1 = document.getElementById('estimate1Input');
            if (input1) {
                input1.min = round.input1Min;
                input1.max = round.input1Max;
                input1.value = round.input1Default;
                input1.step = round.input1Step;
            }

            var input2 = document.getElementById('estimate2Input');
            if (input2) {
                input2.min = round.input2Min;
